drills.solution:
export class NotFoundError extends Error {
  name = 'NotFoundError';
}

export class ValidationError extends Error {
  name = 'ValidationError';
  constructor(details, options) {
    super('Validation failed', options);
    this.details = details;
  }
}

export function toProblem(err) {
  if (err instanceof NotFoundError) return { status: 404, title: 'Not Found', detail: err.message };
  if (err instanceof ValidationError) return { status: 400, title: 'Validation failed', errors: err.details };
  return { status: 500, title: 'Internal Server Error' };
}

tests.code:
const p = mod.toProblem(new Error('SELECT * FROM users failed: syntax error at line 1'));
assert.deepEqual(p, { status: 500, title: 'Internal Server Error' });
assert.deepEqual(mod.toProblem('a thrown string'), { status: 500, title: 'Internal Server Error' });
assert.deepEqual(mod.toProblem(undefined), { status: 500, title: 'Internal Server Error' });

const nf = new mod.NotFoundError('x');
const ve = new mod.ValidationError([]);
assert.ok(nf instanceof Error && ve instanceof Error);
assert.equal(nf.name, 'NotFoundError');
assert.equal(ve.name, 'ValidationError');
assert.equal(ve.message, 'Validation failed');
assert.equal(String(nf), 'NotFoundError: x');

drills.explanation:
Name fields make the classes print and log properly; `instanceof` picks the response:

```js
export function toProblem(err) {
  if (err instanceof NotFoundError) return { status: 404, title: 'Not Found', detail: err.message };
  if (err instanceof ValidationError) return { status: 400, title: 'Validation failed', errors: err.details };
  return { status: 500, title: 'Internal Server Error' };
}
```

The fallback deliberately ignores the message: for an unknown error it may contain SQL, file paths or secrets, so log it server-side instead. Without the `name` field a subclass still reports 'Error', and the test "the classes are real, named Errors" fails. Calling `super('Validation failed')` without `options` drops the cause, and "a ValidationError keeps its cause" fails. Branching on `err.name` instead of `instanceof` crashes on `toProblem(undefined)`, so "unexpected errors never leak their message" fails with a TypeError.

